import type { Metadata } from 'next'
import type { ComponentType, ReactNode } from 'react'

import { TRANSLATED_PAGES } from './pages.generated'

export interface TranslatedPage {
  load: () => Promise<{ default: ComponentType; metadata?: Metadata }>
  /** The English page's layouts below the site shell, outermost first. */
  layouts: readonly ComponentType<{ children: ReactNode }>[]
}

// Generated by script.js from every page.ko.mdx / page.ko.tsx beside its
// English source, so a translation needs no registration here.
export const translatedPages: Readonly<
  Record<string, TranslatedPage | undefined>
> = TRANSLATED_PAGES
